const KEY = 'ayn-academy-v2';
const blank = () => ({user:null, done:{}, vid:{}, best:{}, cert:{}, certDate:{}, tries:{}, role:'', track:'fin', q:[]});
let S = blank();
const ls = {get:k=>{try{return localStorage.getItem(k);}catch(e){return null;}}, set:(k,v)=>{try{localStorage.setItem(k,v);}catch(e){}}, del:k=>{try{localStorage.removeItem(k);}catch(e){}}};
const ukey = u => u ? (u.demo ? 'demo:'+norm(u.name).replace(/\s+/g,'_') : 'p:'+u.pk) : '';
function save(){ if(!S.user) return; ls.set(KEY+':'+ukey(S.user), JSON.stringify(S)); ls.set(KEY+':last', ukey(S.user)); }
function loadUser(uk){ const raw = ls.get(KEY+':'+uk); if(!raw) return null; try{ return Object.assign(blank(), JSON.parse(raw)); }catch(e){ return null; } }
(function boot(){ const last = ls.get(KEY+':last'); if(last){ const st = loadUser(last); if(st && st.user) S = st; } })();

