function note(kind, title, body){
  const icn = kind==='warn' ? I.alert : kind==='tip' ? I.info : I.star;
  return `<div class="note ${kind}"><div class="ic">${icn}</div><div><b>${title}</b><div>${body}</div></div></div>`;
}
function fig(src, cap){ return `<figure class="fig"><button data-zoom="assets/${src}.webp" data-cap="${esc(cap)}" aria-label="تكبير الصورة"><img src="assets/${src}.webp" alt="${esc(cap)}" loading="lazy"></button><figcaption>${cap}</figcaption></figure>`; }
function ring(p, size=30, stroke=4, col='#2CC0CC', bg='rgba(255,255,255,.18)'){
  const r=(size-stroke)/2, c=2*Math.PI*r;
  const lbl = size>=60 ? `<text x="50%" y="50%" text-anchor="middle" dominant-baseline="central" style="fill:var(--ink);font-family:var(--f-mono);font-weight:600;font-size:${size*.22}px">${Math.round(p*100)}%</text>` : '';
  return `<svg class="ring" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}"><circle cx="${size/2}" cy="${size/2}" r="${r}" style="stroke:${bg};fill:none" stroke-width="${stroke}"/><circle cx="${size/2}" cy="${size/2}" r="${r}" style="stroke:${col};fill:none" stroke-width="${stroke}" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${c*(1-p)}" transform="rotate(-90 ${size/2} ${size/2})"/>${lbl}</svg>`;
}
let toastT;
function toast(msg){ let t=$('.toast'); if(!t){t=document.createElement('div');t.className='toast';t.setAttribute('role','status');document.body.appendChild(t);} t.textContent=msg; t.hidden=false; clearTimeout(toastT); toastT=setTimeout(()=>t.hidden=true,2800); }

/* ================= registries (tracks.js extends these) ================= */
const V = {}, AFTER = {}, ACT = {}, INP = {}, SEARCHX = [];
const TRACKS = {}, TORDER = [], MOD = {};
function defTrack(id, o){
  TRACKS[id] = Object.assign({id}, o); TORDER.push(id);
  o.mods.forEach((m,i)=>{ m.tr=id; m.i=i; MOD[m.id]=m; });
  V['t-'+id] = () => trackView(id);
  V['exam-'+id] = () => examView(id);
  V['cert-'+id] = () => certView(id);
}
const coreOf = tr => TRACKS[tr].mods.filter(m=>!m.opt);
const tpct = tr => { const c=coreOf(tr); return c.length ? c.filter(m=>S.done[m.id]).length/c.length : 0; };
const tmin = tr => coreOf(tr).reduce((a,m)=>a+m.min,0);
const passed = tr => S.best[tr]!=null && S.best[tr]>=PASS;
const ROLES = {
 rep:{t:'مندوب ميداني',d:'يستلم التبرعات من المحسنين في الميدان ويصفّي ما بذمته في الفرع أو المكتب.',ic:I.walk},
 site:{t:'موظف موقع',d:'يستلم التبرعات في مواقع المؤسسة (الأكشاك) التابعة للمكتب أو للفرع.',ic:I.kiosk},
 rec:{t:'موظف استقبال',d:'يستقبل المحسنين ويستلم تبرعاتهم داخل الفرع أو المكتب.',ic:I.desk}
};

/* ================= sync with the department sheet ================= */
let SYNC = LIVE ? 'idle' : 'demo', FL = false;
async function api(action, body){
  const res = await fetch(API_URL, {method:'POST', headers:{'Content-Type':'text/plain;charset=utf-8'}, body:JSON.stringify(Object.assign({action}, body||{}))});
  if(!res.ok) throw new Error('http '+res.status);
  return res.json();
}
function snapshot(){
  const tracks = {};
  TORDER.forEach(tr=>{ const c=coreOf(tr); tracks[tr] = {t:TRACKS[tr].short, done:c.filter(m=>S.done[m.id]).length, total:c.length, best:S.best[tr]??null, pass:passed(tr), tries:S.tries[tr]||0, cert:S.cert[tr]||'', certDate:S.certDate[tr]||''}; });
  return {tracks, done:Object.keys(S.done).filter(k=>S.done[k]), vid:Object.keys(S.vid).filter(k=>S.vid[k]&&S.vid[k].ok), role:S.role};
}
function send(ev, data){
  if(!S.user || S.user.demo || !LIVE) return;
  S.q.push(Object.assign({ev, at:new Date().toISOString()}, data||{})); save(); flush();
}
function flush(){
  if(!LIVE || !S.user || S.user.demo || FL || !S.q.length) { syncUI(); return; }
  FL = true; SYNC = 'busy'; syncUI();
  const batch = S.q.slice(0, 25);
  api('events', {token:S.user.token, events:batch, snap:snapshot()}).then(r=>{
    if(r && r.ok){ S.q.splice(0, batch.length); save(); SYNC='ok'; }
    else if(r && r.error==='auth'){ SYNC='auth'; }
    else SYNC='off';
  }).catch(()=>{ SYNC='off'; }).finally(()=>{ FL=false; syncUI(); if(S.q.length && SYNC==='ok') setTimeout(flush, 600); });
}
window.addEventListener('online', ()=>flush());
setInterval(()=>{ if(S.q && S.q.length) flush(); }, 60000);
function syncText(){
  if(!S.user) return '';
  if(S.user.demo) return LIVE ? 'نسخة عرض' : 'نسخة عرض — النتائج لا تُرسل';
  if(SYNC==='auth') return 'انتهت الجلسة — سجّل الدخول مجدداً';
  if(S.q.length) return SYNC==='off' ? `غير متصل — ${S.q.length} بانتظار الإرسال` : 'جارٍ الإرسال…';
  return 'متصل بسجل القسم';
}
function syncUI(){ const el=$('#syncSt'); if(el){ el.textContent = syncText(); el.dataset.s = S.user&&S.user.demo ? 'demo' : (SYNC==='auth'||SYNC==='off') ? 'bad' : S.q.length ? 'wait' : 'ok'; } }

