async function doLogin(){
  const name = ($('#lgName')?.value||'').trim().replace(/\s+/g,' '), phone = $('#lgPhone')?.value||'';
  LG.name = name; LG.phone = phone; LG.err = '';
  const pk = phoneKey(phone);
  if(name.split(' ').length < 3){ LG.err = 'اكتب اسمك الثلاثي كاملاً كما هو مسجّل في المؤسسة.'; return loginView(); }
  if(!/^7\d{9}$/.test(pk)){ LG.err = 'رقم الهاتف غير صحيح: 11 رقماً يبدأ بـ 07.'; return loginView(); }
  if(!LIVE){ startSession({name, pk, branch:'', office:'', trainer:'', demo:true, ph4:pk.slice(-4)}); return; }
  LG.busy = true; loginView();
  try{
    const r = await api('login', {name, phone:pk});
    LG.busy = false;
    if(r && r.ok){
      const u = Object.assign({pk, ph4:pk.slice(-4)}, r.user, {token:r.token});
      const needT = !u.trainer && r.trainers && r.trainers.length;
      startSession(u, r.progress, !needT);
      if(needT){ LG.trainers = r.trainers; LG.step = 'trainer'; loginView(); }
      return;
    }
    LG.err = r && r.error==='locked' ? 'محاولات كثيرة خاطئة. انتظر ربع ساعة ثم أعد المحاولة.' : 'الاسم أو رقم الهاتف غير موجود في سجل المندوبين. اكتب اسمك كما هو مسجّل، أو راجع مدربك.';
  }catch(e){ LG.busy=false; LG.err = 'تعذّر الاتصال بالسجل. تحقق من الإنترنت وأعد المحاولة.'; }
  loginView();
}
function mergeProgress(p){
  if(!p) return;
  (p.done||[]).forEach(id=>{ S.done[id]=true; });
  (p.vid||[]).forEach(id=>{ S.vid[id]=Object.assign(S.vid[id]||{w:'',d:0,cp:{}},{ok:true}); });
  const tr = p.tracks||{};
  Object.keys(tr).forEach(k=>{ const t=tr[k]; if(t.best!=null && (S.best[k]==null || t.best>S.best[k])) S.best[k]=t.best; if(t.cert && !S.cert[k]){ S.cert[k]=t.cert; S.certDate[k]=t.certDate; } if(t.tries>(S.tries[k]||0)) S.tries[k]=t.tries; });
  if(p.role && !S.role) S.role = p.role;
}
function startSession(u, progress, render=true){
  const st = loadUser(ukey(u));
  S = st || blank(); S.user = Object.assign(S.user||{}, u);
  mergeProgress(progress); save();
  LG = {step:'form', err:'', busy:false, trainers:[], name:'', phone:''};
  if(render) enterApp();
  flush();
}
function enterApp(){ shell(); if(location.hash && location.hash!=='#home') route(); else if(location.hash==='#home') route(); else location.hash = '#home'; }
function logout(){ save(); ls.del(KEY+':last'); S = blank(); location.hash = ''; loginView(); }

