function curTrack(key){ if(MOD[key]) return MOD[key].tr; const m = /^(t|exam|cert)-(\w+)$/.exec(key); if(m && TRACKS[m[2]]) return m[2]; return S.track && TRACKS[S.track] ? S.track : TORDER[0]; }
function rail(cur){
  const tr = curTrack(cur), T = TRACKS[tr], mods = T.mods;
  const item = (m,i) => `<li><a class="rail-item ${cur===m.id?'on':''} ${S.done[m.id]?'done':''}" href="#${m.id}"><span class="rn">${S.done[m.id]?'✓':pad2(i+1)}</span><span>${m.t}<small>${m.s}</small></span>${m.opt?'<span class="tag">ملحق</span>':(needVid(m.id)&&!vidOk(m.id)?`<span class="vtag" title="فيديو">${ic(I.play,11)}</span>`:'')}</a></li>`;
  const ready = coreOf(tr).every(m=>S.done[m.id]);
  $('#rail').innerHTML = `
   <div class="rail-tracks" role="tablist" aria-label="المسارات">${TORDER.map(k=>`<a href="#t-${k}" class="rt ${k===tr?'on':''} ${passed(k)?'ok':''}" title="${TRACKS[k].t}">${ic(TRACKS[k].ic,18)}<span>${TRACKS[k].short}</span></a>`).join('')}</div>
   <ul class="rail-list">
   <li><a class="rail-item ${cur==='home'?'on':''}" href="#home"><span class="rn">⌂</span><span>الرئيسية<small>مساراتي وإنجازي</small></span></a></li>
   <li><a class="rail-item ${cur==='t-'+tr?'on':''}" href="#t-${tr}"><span class="rn">${ic(T.ic,16)}</span><span>${T.t}<small>نظرة على المسار</small></span></a></li>
   <li class="rail-sep"></li>
   ${mods.map(item).join('')}
   <li class="rail-sep"></li>
   <li><a class="rail-item ${cur==='exam-'+tr?'on':''} ${passed(tr)?'done':''}" href="#exam-${tr}"><span class="rn">${ready||passed(tr)?'✎':ic(I.lock,15)}</span><span>اختبار ${T.short}<small>${Math.min(T.n,T.bank.length)} سؤالاً — النجاح ${PASS}٪</small></span></a></li>
   <li><a class="rail-item ${cur==='cert-'+tr?'on':''}" href="#cert-${tr}"><span class="rn">★</span><span>شهادة ${T.short}<small>${S.cert[tr]?'صادرة':'بعد اجتياز الاختبار'}</small></span></a></li></ul>`;
}

/* ================= generic module parts ================= */
function modHead(id, eyebrow, lead){
  const m = MOD[id], T = TRACKS[m.tr];
  return `<header class="mod-head"><div class="serial">${T.t} · الوحدة <i>${pad2(m.i+1)} / ${pad2(T.mods.length)}</i></div><h1>${m.t}</h1><p>${lead}</p><div class="meta"><span>${m.min} دقائق</span><span>${eyebrow}</span>${needVid(id)?'<span>فيديو شرح</span>':''}${m.opt?'<span>ملحق اختياري</span>':''}</div><div class="perf"></div></header>`;
}
function learn(items){ return `<div class="learn">${items.map(t=>`<div>${t}</div>`).join('')}</div>`; }
function modFoot(id){
  const m = MOD[id], mods = TRACKS[m.tr].mods, nx = mods[m.i+1], pv = mods[m.i-1];
  const lockV = needVid(id) && !vidOk(id) && !S.done[id];
  const doneBtn = lockV ? `<button class="btn btn-ghost" disabled title="شاهد فيديو الوحدة أولاً">${ic(I.lock,16)} شاهد الفيديو لإتمام الوحدة</button>`
    : `<button class="btn ${S.done[id]?'btn-ghost':'btn-navy'}" data-act="done" data-v="${id}">${S.done[id]?'✓ أُنجزت الوحدة':'أتممت هذه الوحدة'}</button>`;
  return `<div class="mod-foot"><div class="row">${pv?`<a class="btn btn-ghost" href="#${pv.id}">${I.prev} السابق</a>`:''}</div>
  <div class="row">${doneBtn}${nx?`<a class="btn btn-primary" href="#${nx.id}">التالي: ${nx.t} ${I.next}</a>`:`<a class="btn btn-primary" href="#exam-${m.tr}">إلى اختبار المسار ${I.next}</a>`}</div></div>`;
}
function refreshFoot(id){ const f=$('.mod-foot'); if(f){ f.outerHTML = modFoot(id); } rail(id); }

/* quick check — QX per module, else first two bank questions of the module */
const QX = {};
function qcFor(id){ if(QX[id]) return QX[id]; const m = MOD[id]; return m ? TRACKS[m.tr].bank.filter(b=>b.m===id).slice(0,2) : []; }
function qc(id){
  const qs = qcFor(id); if(!qs.length) return '';
  return `<section class="qc"><div class="qc-h">${ic(I.check)} تحقّق سريع</div><div class="qc-b">${qs.map((x,qi)=>`
   <div class="stack" style="gap:8px" data-qc="${id}-${qi}"><p class="q-text">${qi+1}. ${x.q}</p><div class="opts">${x.o.map((o,oi)=>`<button class="opt" data-act="qc" data-q="${id}-${qi}" data-o="${oi}"><span class="k">${'أبجد'[oi]}</span><span>${o}</span></button>`).join('')}</div><div class="why" hidden></div></div>`).join('')}</div></section>`;
}

/* ---------- reusable widgets ---------- */
const STP = {}, STPD = {};
function stepper(key, steps){ STPD[key] = steps; if(STP[key]==null) STP[key]=0; return `<div class="stp" data-stp="${key}"></div>`; }
function stpRender(key){
  const el = document.querySelector(`[data-stp="${key}"]`); if(!el) return;
  const st = STPD[key], i = Math.max(0, Math.min(st.length-1, STP[key]||0)), [img,t,d] = st[i];
  el.innerHTML = `<div class="ostep"><div class="stack" style="gap:8px"><span class="on">الخطوة ${i+1} من ${st.length}</span><h3>${t}</h3><p>${d}</p><div class="row"><button class="btn btn-ghost" data-act="stp" data-k="${key}" data-v="${i-1}" ${i===0?'disabled':''}>${I.prev} السابق</button><button class="btn btn-primary" data-act="stp" data-k="${key}" data-v="${i+1}" ${i===st.length-1?'disabled':''}>التالي ${I.next}</button></div></div>${img?fig(img,t):`<div class="stp-noimg">${ic(I.device,44)}</div>`}</div>
   <div class="dots">${st.map((_,j)=>`<button class="${j===i?'on':''}" data-act="stp" data-k="${key}" data-v="${j}" aria-label="الخطوة ${j+1}">${j+1}</button>`).join('')}</div>`;
}
const stpAll = () => $$('[data-stp]').forEach(e=>stpRender(e.dataset.stp));
const TBS = {}, TBD = {};
function tabset(key, tabs){ TBD[key] = tabs; if(TBS[key]==null) TBS[key]=0; return `<div class="tset" data-tset="${key}">${tsetInner(key)}</div>`; }
function tsetInner(key){ const tabs=TBD[key], i=TBS[key]; return `<div class="tabs" role="tablist">${tabs.map(([l],j)=>`<button class="tab ${j===i?'on':''}" role="tab" aria-selected="${j===i}" data-act="tabk" data-k="${key}" data-v="${j}">${l}</button>`).join('')}</div><div class="tset-b">${typeof tabs[i][1]==='function'?tabs[i][1]():tabs[i][1]}</div>`; }
function flips(list, lab=['✗ الخطأ','✓ الصواب'], hint=['اضغط لرؤية الصواب','اضغط للعودة']){
  return `<div class="flips">${list.map(([f,b],i)=>`<button class="flip" data-act="flip" aria-label="اقلب البطاقة ${i+1}"><span class="flip-in"><span class="face f"><span class="fh"><span>${lab[0]}</span><span class="fn">${pad2(i+1)}</span></span><span class="fp">${f}</span><span class="ft">${hint[0]}</span></span><span class="face b"><span class="fh"><span>${lab[1]}</span><span class="fn">${pad2(i+1)}</span></span><span class="fp">${b}</span><span class="ft">${hint[1]}</span></span></span></button>`).join('')}</div>`;
}
const WZS = {}, WZD = {};
function wizard(key, tree, verdicts, warnFn){ WZD[key] = {tree, verdicts, warnFn}; if(!WZS[key]) WZS[key]=['start']; return `<section class="card pad wiz" data-wz="${key}"></section>`; }
function wzRender(key){
  const el = document.querySelector(`[data-wz="${key}"]`); if(!el) return;
  const {tree, verdicts, warnFn} = WZD[key], P = WZS[key], cur = P[P.length-1];
  const labels = []; for(let i=1;i<P.length;i++){ const prev=tree[P[i-1]]; const o=prev&&prev.o.find(x=>x[0]===P[i]); if(o) labels.push(o[1]); }
  const trail = labels.length ? `<div class="wiz-trail">${labels.map(l=>`<span>${l}</span>`).join('<i>←</i>')}</div>` : '';
  if (tree[cur]){ const n=tree[cur];
    el.innerHTML = `${trail}<p class="wiz-q">${n.q}</p><div class="wiz-opts">${n.o.map(([k,t,d])=>`<button class="wiz-opt" data-act="wz" data-k="${key}" data-v="${k}"><b>${t}</b>${d?`<small>${d}</small>`:''}</button>`).join('')}</div>${P.length>1?`<div class="row"><button class="btn btn-ghost" data-act="wzback" data-k="${key}">${I.prev} رجوع</button></div>`:''}`;
  } else { const v=verdicts[cur];
    el.innerHTML = `${trail}<div class="verdict"><div class="vh"><span class="vb ${v.b}">${v.t}</span></div><ol class="steps">${v.s.map(x=>`<li><div>${x}</div></li>`).join('')}</ol></div>${warnFn?warnFn(cur):''}
     <div class="row"><button class="btn btn-ghost" data-act="wzback" data-k="${key}">${I.prev} رجوع</button><button class="btn btn-primary" data-act="wzreset" data-k="${key}">حالة جديدة</button></div>`;
  }
}
const wzAll = () => $$('[data-wz]').forEach(e=>wzRender(e.dataset.wz));
let CPN = 0;
function copyBox(text, title){ const id='cp'+(++CPN); return `<div class="cpy">${title?`<div class="cpy-h"><b>${title}</b><button class="btn btn-ghost btn-sm" data-act="cp" data-src="${id}">${ic(I.copy,16)} نسخ</button></div>`:''}<pre id="${id}">${esc(text)}</pre>${title?'':`<button class="btn btn-ghost btn-sm" data-act="cp" data-src="${id}">${ic(I.copy,16)} نسخ</button>`}</div>`; }
function cardList(items, cols=2){ return `<div class="grid-${cols}">${items.map(([t,d,tone])=>`<div class="card pad stack ${tone?'tone-'+tone:''}" style="gap:6px"><b class="ct">${t}</b>${d?`<p class="muted">${d}</p>`:''}</div>`).join('')}</div>`; }
function bullets(items){ return `<ul class="bul">${items.map(t=>`<li>${t}</li>`).join('')}</ul>`; }
function steps(items){ return `<ol class="steps">${items.map(t=>`<li><div>${t}</div></li>`).join('')}</ol>`; }

/* ================= video gate ================= */
function ytId(u){ const s=String(u||'').trim(); const m=s.match(/(?:youtu\.be\/|v=|embed\/|shorts\/|live\/)([\w-]{11})/); return m ? m[1] : (/^[\w-]{11}$/.test(s) ? s : ''); }
const YFAIL = {};
function vcfg(id){ const v = VIDS[id]; if(!v) return null;
  if(v.yt){ const y=ytId(v.yt); if(y && !YFAIL[y]) return {kind:'yt', id:y, checks:v.checks||[]}; if(y) return {kind:'ig', url:'https://www.youtube.com/watch?v='+y, sec:+v.sec||120, yfail:true}; }
  if(v.ig) return {kind:'ig', url:v.ig, sec:+v.sec||60}; return null; }
function needVid(id){ return !!vcfg(id); }
function vidOk(id){ return !needVid(id) || !!(S.vid[id] && S.vid[id].ok); }
function vst(id){ return S.vid[id] = S.vid[id] || {w:'', d:0, cp:{}, ok:false}; }
function vpct(id){ const s=S.vid[id]; if(!s) return 0; if(s.ok) return 1; if(!s.d) return 0; let n=0; for(const ch of s.w) if(ch==='1') n++; return Math.min(1, n/s.d); }
function vblock(id){
  const c = vcfg(id); if(!c) return '';
  const ok = vidOk(id), p = vpct(id);
  const head = `<div class="vid-h"><span class="vid-badge">${ic(I.play,14)} فيديو الوحدة</span><b id="vidState">${ok?'✓ اكتملت المشاهدة — يمكنك إتمام الوحدة':'شاهد الفيديو حتى النهاية لفتح إتمام الوحدة'}</b></div>`;
  if(c.kind==='yt'){
    if(!STANDALONE) return `<section class="vid">${head}<div class="vid-off">${ic(I.play,28)}<p>يعمل الفيديو في نسخة الموقع المنشورة على GitHub Pages. في نسخة العرض هذه يظهر مكانه فقط.</p></div></section>`;
    return `<section class="vid">${head}<div class="vid-box"><div id="ytp"></div><div class="vid-ov" id="vidOv" hidden></div></div>
      <div class="vid-meter"><div class="vbar"><i id="vidBar" style="width:${p*100}%"></i><span class="need" style="inset-inline-start:${WATCH*100}%" title="المطلوب"></span></div><span id="vidPct" class="mono">${Math.round(p*100)}%</span></div>
      <p class="vid-rule">تُحتسب الثواني التي تُشاهَد فعلاً فقط. التقديم السريع لا يُحتسب، ويتوقف العرض تلقائياً عند مغادرة الصفحة. المطلوب ${Math.round(WATCH*100)}٪${c.checks.length?` مع الإجابة عن ${c.checks.length===1?'سؤال تحقق':c.checks.length+' أسئلة تحقق'} أثناء المشاهدة`:''}.</p></section>`;
  }
  const st = S.vid[id]||{}, left = st.igAt ? Math.max(0, c.sec - Math.floor((Date.now()-st.igAt)/1000)) : c.sec;
  return `<section class="vid">${head}<div class="vid-ig"><a class="btn btn-primary" href="${esc(c.url)}" target="_blank" rel="noopener" data-act="igopen" data-v="${id}">${ic(I.play,16)} افتح مقطع الشرح</a>
    <span id="igT" class="muted">${ok?'':st.igAt?(left>0?`يُفتح التأكيد بعد ${left} ثانية`:'يمكنك التأكيد الآن'):`مدة المقطع ${c.sec} ثانية تقريباً`}</span>
    <label class="s-check"><input type="checkbox" data-in="igok" data-v="${id}" ${ok?'checked disabled':(!st.igAt||left>0?'disabled':'')}> شاهدت المقطع كاملاً</label></div>${c.yfail?'<p class="vid-rule">تعذّر تشغيل هذا الفيديو داخل الموقع (صاحب القناة منع عرضه في المواقع الأخرى أو أنه غير متاح)، لذلك يُفتح على YouTube ويُحتسب بعداد مدته.</p>':''}</section>`;
}
let YP = null, YTT = null, YLAST = null, YCUR = null, IGT = null;
function ytLoad(cb){
  if(window.YT && YT.Player) return cb();
  (window.__ytq = window.__ytq || []).push(cb);
  if(!document.getElementById('yt-api')){ const s=document.createElement('script'); s.id='yt-api'; s.src='https://www.youtube.com/iframe_api'; document.head.appendChild(s);
    window.onYouTubeIframeAPIReady = ()=>{ const q=window.__ytq||[]; window.__ytq=[]; q.forEach(f=>f()); }; }
}
function vidCleanup(){ clearInterval(YTT); clearInterval(IGT); YLAST=null; if(YP && YP.destroy){ try{ YP.destroy(); }catch(e){} } YP=null; YCUR=null; }
function vidMount(id){
  const c = vcfg(id); if(!c) return;
  if(c.kind==='ig'){ igTick(id); IGT=setInterval(()=>igTick(id),1000); return; }
  if(!STANDALONE || !$('#ytp')) return;
  const st = vst(id); YCUR = id;
  ytLoad(()=>{
    if(YCUR!==id || !$('#ytp')) return;
    YP = new YT.Player('ytp', {videoId:c.id, playerVars:{rel:0, modestbranding:1, playsinline:1, hl:'ar'}, events:{
      onReady:()=>{ const d=Math.floor(YP.getDuration()||0); if(d){ st.d=d; if(st.w.length<d) st.w = st.w.padEnd(d,'0'); save(); } vidUI(id); },
      onStateChange:e=>{ if(e.data===YT.PlayerState.PLAYING){ YLAST=YP.getCurrentTime(); clearInterval(YTT); YTT=setInterval(()=>vidTick(id),500); } else { clearInterval(YTT); if(e.data===YT.PlayerState.ENDED) vidTick(id); YLAST=null; } },
      onError:()=>{ YFAIL[c.id]=true; vidCleanup(); const sec=$('section.vid'); if(sec) sec.outerHTML = vblock(id); vidMount(id); }
    }});
  });
}
function vidTick(id){
  if(!YP || !YP.getCurrentTime) return;
  const st = vst(id), c = vcfg(id), t = YP.getCurrentTime();
  if(!st.d){ const d=Math.floor(YP.getDuration()||0); if(d){ st.d=d; st.w=st.w.padEnd(d,'0'); } }
  if(YLAST!=null && t>=YLAST && t-YLAST<=1.25 && st.d){
    const a=Math.floor(YLAST), b=Math.min(st.d-1, Math.floor(t)); let w=st.w.split(''); for(let k=a;k<=b;k++) w[k]='1'; st.w=w.join('');
  }
  YLAST = t;
  const ci = (c.checks||[]).findIndex((q,i)=>!st.cp[i] && t>=q.at);
  if(ci>-1){ YP.pauseVideo(); showCheck(id, ci); }
  vidUI(id); save();
}
function vidUI(id){
  const st = vst(id), c = vcfg(id), p = vpct(id);
  const b=$('#vidBar'); if(b) b.style.width=(p*100)+'%'; const t=$('#vidPct'); if(t) t.textContent=Math.round(p*100)+'%';
  const allCp = (c.checks||[]).every((_,i)=>st.cp[i]);
  if(!st.ok && p>=WATCH && allCp){ st.ok = true; save(); send('video', {mod:id, tr:MOD[id].tr, pct:Math.round(p*100)}); toast('اكتملت مشاهدة الفيديو — يمكنك إتمام الوحدة'); const s=$('#vidState'); if(s) s.textContent='✓ اكتملت المشاهدة — يمكنك إتمام الوحدة'; refreshFoot(id); }
}
function showCheck(id, i){
  const q = vcfg(id).checks[i], ov = $('#vidOv'); if(!ov) return;
  ov.hidden = false;
  ov.innerHTML = `<div class="vq"><span class="eyebrow" style="color:#9FE6EC">سؤال تحقق</span><p>${q.q}</p><div class="opts">${q.o.map((o,oi)=>`<button class="opt" data-act="vq" data-v="${id}" data-i="${i}" data-o="${oi}"><span class="k">${'أبجدهـ'[oi]}</span><span>${o}</span></button>`).join('')}</div><div class="vq-msg" id="vqMsg"></div></div>`;
}
function igTick(id){
  const c=vcfg(id), st=S.vid[id]; const t=$('#igT'), cb=$('[data-in="igok"]'); if(!t||!st||!st.igAt||st.ok) return;
  const left = Math.max(0, c.sec - Math.floor((Date.now()-st.igAt)/1000));
  t.textContent = left>0 ? `يُفتح التأكيد بعد ${left} ثانية` : 'يمكنك التأكيد الآن'; if(cb) cb.disabled = left>0;
}
document.addEventListener('visibilitychange', ()=>{ if(document.hidden && YP && YP.pauseVideo){ try{ YP.pauseVideo(); }catch(e){} } });

/* ================= hub, track page, profile ================= */
function trackStatus(tr){
  const p=tpct(tr);
  if(passed(tr)) return ['ok',`ناجح · ${S.best[tr]}٪`];
  if(p>=1) return ['ready','جاهز للاختبار'];
  if(p>0) return ['go',`جارٍ · ${Math.round(p*100)}٪`];
  return ['new','لم يبدأ'];
}
