      <div class="cta"><a class="btn btn-primary" href="#${nextMod?nextMod.id:'exam-'+nextTr}">${overall>0?'تابع من حيث توقفت':'ابدأ التدريب'} ${I.next}</a><a class="btn btn-ghost" href="#me">ملفي وسجلّي</a></div>
