/* ================= exam & certificate (per track) ================= */
const EXS = {};
function examStart(tr){ const B=TRACKS[tr].bank, n=Math.min(TRACKS[tr].n, B.length); const idx = B.map((_,i)=>i).sort(()=>Math.random()-.5).slice(0,n); EXS[tr] = {q:idx, i:0, ans:[], done:false, n}; }
function examView(tr){
  const T = TRACKS[tr];
  return `<div class="stack"><header class="mod-head"><div class="serial">${T.t} · <i>الاختبار</i></div><h1>اختبار ${T.t}</h1><p>أسئلة مبنية على مواقف حقيقية من عمل المستحصل اليومي، وكل إجابة مستندة إلى نص الدليل المعتمد.</p><div class="perf"></div></header><section class="card pad" id="exam" data-tr="${tr}"></section></div>`;
}
function examRender(tr){
  const el=$('#exam'); if(!el) return; const T=TRACKS[tr], B=T.bank, EX=EXS[tr];
  const missing = coreOf(tr).filter(m=>!S.done[m.id]);
  if(missing.length && !passed(tr)){
    el.innerHTML = `<div class="stack" style="gap:14px"><div class="locked">${ic(I.lock,28)}<div><h3>الاختبار مغلق</h3><p class="muted">يُفتح بعد إتمام الوحدات الأساسية للمسار${Object.keys(VIDS).length?' ومشاهدة فيديوهاتها':''}. المتبقي:</p></div></div>
     <div class="path">${missing.map(m=>`<a href="#${m.id}"><span class="pn">${pad2(m.i+1)}</span><span><b>${m.t}</b><small>${needVid(m.id)&&!vidOk(m.id)?'الفيديو لم يكتمل':'لم تُتمّ بعد'}</small></span></a>`).join('')}</div></div>`;
    return;
  }
  const n = Math.min(T.n, B.length), need = Math.ceil(n*PASS/100);
  if (!EX){ el.innerHTML = `<div class="stack" style="gap:14px"><p class="lead">${n} سؤالاً تُختار عشوائياً من بنك من ${B.length} سؤالاً يغطي وحدات المسار. درجة النجاح ${PASS}٪ (${need} إجابة صحيحة). تظهر الإجابات والتعليل بعد الانتهاء${LIVE&&!S.user.demo?'، وتُرسل نتيجتك إلى سجل القسم':''}.</p>${S.best[tr]!=null?`<span class="score-pill">أفضل نتيجة سابقة: ${S.best[tr]}٪ · المحاولات: ${S.tries[tr]||0}</span>`:''}<button class="btn btn-primary" data-act="exstart" data-v="${tr}" style="justify-self:start">ابدأ الاختبار ${I.next}</button></div>`; return; }
  if (!EX.done){
    const b = B[EX.q[EX.i]], sel = EX.ans[EX.i];
    el.innerHTML = `<div class="stack" style="gap:14px"><div class="exam-top"><span class="qnum">السؤال ${EX.i+1} من ${EX.n}</span><span class="qnum">${MOD[b.m]?.t||''}</span></div><div class="qbar"><i style="width:${(EX.i/EX.n)*100}%"></i></div>
     <p class="q-text" style="font-size:1.1rem">${b.q}</p><div class="opts">${b.o.map((o,oi)=>`<button class="opt ${sel===oi?'sel':''}" data-act="exans" data-v="${tr}" data-o="${oi}"><span class="k">${'أبجد'[oi]}</span><span>${o}</span></button>`).join('')}</div>
     <div class="row" style="justify-content:space-between"><button class="btn btn-ghost" data-act="exprev" data-v="${tr}" ${EX.i===0?'disabled':''}>${I.prev} السابق</button><button class="btn btn-primary" data-act="exnext" data-v="${tr}" ${sel===undefined?'disabled':''}>${EX.i===EX.n-1?'إنهاء وتصحيح':'التالي'} ${I.next}</button></div></div>`;
    return;
  }
  const right = EX.q.filter((qi,i)=>EX.ans[i]===B[qi].a).length, sc = Math.round(right/EX.n*100), pass = sc>=PASS;
  el.innerHTML = `<div class="stack"><div class="result">${ring(sc/100,130,12,pass?'var(--ok)':'var(--bad)','var(--surface-3)').replace('class="ring"','class="bigscore"')}<div class="stack" style="gap:8px"><h2 style="font-size:1.6rem">${pass?'ناجح — مبارك':'لم تبلغ درجة النجاح بعد'}</h2><p class="lead"><b class="mono">${right}</b> إجابة صحيحة من ${EX.n} — <b class="mono">${sc}٪</b></p><div class="row">${pass?`<a class="btn btn-primary" href="#cert-${tr}">اعرض الشهادة ${I.next}</a>`:''}<button class="btn btn-ghost" data-act="exstart" data-v="${tr}">أعد الاختبار</button></div></div></div>
   <div class="sec"><h2>مراجعة الإجابات</h2></div><div class="review">${EX.q.map((qi,i)=>{const b=B[qi], ok=EX.ans[i]===b.a; return `<div class="rv ${ok?'ok':'no'}"><b>${i+1}. ${b.q}</b><span>${ok?'✓':'✗'} إجابتك: ${b.o[EX.ans[i]]}</span>${ok?'':`<span style="color:var(--ok)">الصحيح: ${b.o[b.a]}</span>`}<span class="muted">${b.w}</span></div>`;}).join('')}</div></div>`;
}
function examFinish(tr){
  const EX=EXS[tr], B=TRACKS[tr].bank; EX.done=true;
  const right=EX.q.filter((qi,i)=>EX.ans[i]===B[qi].a).length, sc=Math.round(right/EX.n*100), pass=sc>=PASS;
  S.tries[tr]=(S.tries[tr]||0)+1;
  if(S.best[tr]==null||sc>S.best[tr]) S.best[tr]=sc;
  let newCert = '';
  if(pass && !S.cert[tr]){ const d=new Date(); S.cert[tr] = 'AYN-'+TRACKS[tr].code+'-'+String(d.getFullYear()).slice(2)+pad2(d.getMonth()+1)+String(Date.now()).slice(-4); S.certDate[tr]=d.toLocaleDateString('en-GB'); newCert=S.cert[tr]; }
  save(); send('exam', {tr, score:sc, right, total:EX.n, pass, attempt:S.tries[tr], cert:newCert||S.cert[tr]||''});
}
function certView(tr){
  const T = TRACKS[tr], u = S.user;
  if (!S.cert[tr]) return `<div class="stack"><header class="mod-head"><div class="serial">${T.t} · الشهادة</div><h1>شهادة ${T.t}</h1><p>تصدر الشهادة بعد اجتياز اختبار المسار بنسبة ${PASS}٪ فأكثر.</p><div class="perf"></div></header><section class="card pad stack"><p class="lead">لم تجتز اختبار هذا المسار بعد.</p><a class="btn btn-primary" href="#exam-${tr}" style="justify-self:start">إلى الاختبار ${I.next}</a></section></div>`;
  const role = tr==='fin' ? (ROLES[S.role]?.t || 'مستحصل') : 'مستحصل';
  return `<div class="stack"><section class="card pad stack" style="gap:10px"><div class="row">${STANDALONE?`<button class="btn btn-primary" data-act="print">طباعة الشهادة / حفظ PDF</button>`:`<p class="muted">لحفظ الشهادة التقط صورة للشاشة، أو اطبعها من الموقع المنشور.</p>`}</div></section>
   <div class="cert" id="certCard"><div class="guil"></div><div class="frame"></div><div class="cert-in">
    <div class="c-top"><div style="text-align:start"><b>مؤسسة العين للرعاية الاجتماعية</b>قسم الترويج والاستحصال<br>لجنة تطوير المستحصلين</div><div style="text-align:end">رقم الشهادة<div class="c-ser">${S.cert[tr]}</div></div></div>
    <div class="c-mid"><h2>شهادة إتمام</h2><p>تشهد أكاديمية الاستحصال بأن</p><div class="c-name">${esc(u.name)}</div><p>${role}${u.branch?` — ${esc(u.branch)}`:''} — قد أتمّ <b>${T.t}</b> من البرنامج التدريبي للمستحصلين واجتاز اختباره بنسبة <b class="mono">${S.best[tr]}٪</b></p><p style="font-size:clamp(.55rem,1.3vw,.85rem)">${T.topics}</p></div>
    <div class="c-bot"><div style="text-align:start"><b>التاريخ</b><span class="mono">${S.certDate[tr]}</span>${u.trainer?`<br><b>المدرب</b>${esc(u.trainer)}`:''}</div><div class="seal">أمانة<br>الأيتام</div><div style="text-align:end"><b>المصادقة</b>التوقيع والختم ..................</div></div>
   </div></div></div>`;
}

/* ================= search ================= */
function searchIndex(){
  const out = [];
  TORDER.forEach(tr=>{ out.push({k:'مسار',t:TRACKS[tr].t,s:TRACKS[tr].s,go:'#t-'+tr}); TRACKS[tr].mods.forEach(m=>out.push({k:'وحدة · '+TRACKS[tr].short,t:m.t,s:m.s,go:'#'+m.id})); });
  SEARCHX.forEach(f=>f(out));
  return out.map(o=>Object.assign(o,{n:norm(o.t+' '+o.s)}));
}
let SIDX = null;
function openSearch(){
  SIDX = SIDX || searchIndex();
  const d = document.createElement('div'); d.className='sdlg'; d.innerHTML = `<div class="sdlg-in" role="dialog" aria-label="بحث في الأكاديمية"><input id="sq" placeholder="ابحث عن تبرع، كفالة، صندوق، مادة، حقل، خطأ…" autocomplete="off"><div class="sdlg-list" id="sl"></div></div>`;
  d.addEventListener('click', e=>{ if(e.target===d) d.remove(); });
  document.body.appendChild(d);
  const q=$('#sq',d), l=$('#sl',d);
  const run=()=>{ const toks=norm(q.value).split(/\s+/).filter(Boolean).map(w=>w.replace(/^(وال|بال|لل|ال)(?=..)/,'')); const r = toks.length ? SIDX.filter(o=>toks.every(t=>o.n.includes(t))).slice(0,40) : SIDX.filter(o=>o.k==='مسار');
    l.innerHTML = r.map(o=>`<button class="sitem" data-i="${SIDX.indexOf(o)}"><span class="k">${o.k}</span><span>${esc(o.t)}<small>${esc(o.s)}</small></span></button>`).join('') || '<p class="muted" style="padding:14px">لا توجد نتائج.</p>'; };
  q.addEventListener('input',run); run(); q.focus();
  l.addEventListener('click',e=>{ const b=e.target.closest('.sitem'); if(!b) return; const o=SIDX[+b.dataset.i]; if(o.pre) o.pre(); d.remove(); if(location.hash===o.go) route(); else location.hash=o.go; });
  d.addEventListener('keydown',e=>{ if(e.key==='Escape') d.remove(); });
}

/* ================= router & events ================= */
function route(){
  if(!S.user || LG.step==='trainer'){ loginView(); return; }
  if(!$('#main')) shell();
  vidCleanup();
  const id = (location.hash||'#home').slice(1);
  const key = V[id] ? id : 'home';
  const tr = curTrack(key); if(tr!==S.track){ S.track=tr; save(); }
  rail(key);
  $('#main').innerHTML = V[key]() + `<footer class="footer">قسم الترويج والاستحصال — لجنة تطوير المستحصلين · المحتوى مستند إلى أدلة العمل المعتمدة للمستحصلين</footer>`;
  if(MOD[key] && needVid(key)){ const h=$('.mod-head'); if(h) h.insertAdjacentHTML('afterend', vblock(key)); }
  if(AFTER[key]) AFTER[key]();
  stpAll(); wzAll();
  const ex = /^exam-(\w+)$/.exec(key); if(ex) examRender(ex[1]);
  if(MOD[key]) vidMount(key);
  syncUI();
  $('#rail').classList.remove('open'); $('.scrim').classList.remove('open');
  window.scrollTo(0,0);
}
