const ITEMS = []; CODES.forEach(([c,t,arr])=>arr.forEach(x=>ITEMS.push({c,t,x,n:norm(x+' '+t)})));
function findItems(q){
  const toks = norm(q).split(/\s+/).filter(Boolean).map(w=>w.replace(/^(وال|بال|لل|ال|و)(?=..)/,''));
  if(!toks.length) return [];
  return ITEMS.filter(it=>toks.every(t=>it.n.includes(t)));
}
function hl(text,q){
  let out = esc(text); const toks = q.trim().split(/\s+/).filter(w=>w.length>1);
  toks.forEach(t=>{ const tt = t.replace(/^(وال|بال|لل|ال)(?=..)/,''); if(tt.length<2) return; try{ out = out.replace(new RegExp(tt.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'g'), m=>`<mark>${m}</mark>`);}catch(e){} });
  return out;
}
let FQ = '', OPEN = null, SORTI = 0, SORTS = 0;
function finderRender(){
  const r = $('#fRes'); if(!r) return;
  const res = FQ.trim() ? findItems(FQ) : [];
  r.innerHTML = FQ.trim() ? (res.length ? `<p class="res-meta">${nRes(res.length)} — البيان المعتمد في تحرير الوصل ورمز التبويب</p><div class="results">${res.slice(0,40).map(it=>`<div class="res"><div><div class="st">${hl(it.x,FQ)}</div><div class="ty">نوع الإيراد: ${esc(it.t)}</div></div><div class="codebadge"><small>الرمز</small><b>${it.c}</b></div></div>`).join('')}</div>` : `<div class="note tip"><div class="ic">${I.info}</div><div><b>لا توجد نتيجة مطابقة</b><div>جرّب كلمة أقصر أو مرادفاً (مثلاً «ذبيحة» بدل «ذبح»)، أو تصفّح الرموز بالأسفل.</div></div></div>`) : '';
  const g = $('#fCodes'); if (g) g.innerHTML = CODES.map(([c,t,arr])=>`<button class="code ${OPEN===c?'open':''}" data-act="code" data-v="${c}" aria-expanded="${OPEN===c}"><span class="cn">${c}</span><span><b>${esc(t)}</b><small>${arr.length} ${arr.length>2?'بيانات':'بيان'}</small></span>${OPEN===c?`<ul>${arr.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</button>`).join('');
}
