function paper(kind, data, cls, spot){
  const L = (k, inner) => `<div class="p-line ${spot ? (SPOTDONE ? (data.bad.includes(k)?(SPOT[k]?'okx':'err'):(SPOT[k]?'err':'')) : (SPOT[k]?'hot':'')) : (PHOT===k?'hot':'')}" data-act="${spot?'spot':'pf'}" data-v="${k}" role="button" tabindex="0"><span>${PFIELDS[k][0]}</span>${inner}</div>`;
  const boxes = s => `<span class="p-boxes">${String(s).padStart(8,' ').split('').map(c=>`<i>${c.trim()}</i>`).join('')}</span>`;
  return `<div class="paper ${cls}"><div class="p-head"><div class="p-org">مؤسسة العين للرعاية الاجتماعية<small>AL-AYN Social Care Foundation</small><span class="p-kind">■ وصل قبض مبلغ</span></div><div class="p-ser" data-act="${spot?'':'pf'}" data-v="ser" style="cursor:pointer">رقم الوصل<b>${data.ser}</b></div></div>
   <div class="stamp">تنزيل من<br>الدخل<br>الضريبي</div>
   ${L('date',`<em class="mono" style="direction:ltr">${data.date}</em>`)}
   ${L('from',`<em>${data.from}</em>`)}
   ${L('num',boxes(data.num))}
   ${L('words',`<em>${data.words}</em>`)}
   ${L('for',`<em>${data.for}</em>`)}
   ${L('via',`<em>${data.via}</em>`)}
   ${L('sign',`<em>${data.sign}</em>`)}
   <p class="p-note">ملاحظة / يُعد هذا الوصل مستنداً مؤقتاً يؤيد تسلّم المبلغ إلى حين إصدار وصل القبض النهائي المصادق عليه من قبل رئيس المؤسسة والمشرف العام.</p></div>`;
}
