let KSP = {}, KSPDONE = false;
function kformRender(){
  const el=$('#kform'); if(!el) return;
  el.innerHTML = `<div class="kform"><div class="kf-h"><b>طلب تكفّل يتيم</b><small>مؤسسة العين للرعاية الاجتماعية — نموذج تدريبي</small></div>
   ${KFORM.map(([k,l,v,bad])=>{ const cls = KSPDONE ? (bad ? (KSP[k]?'okx':'err') : (KSP[k]?'err':'')) : (KSP[k]?'hot':''); return `<div class="p-line ${cls}" data-act="kspot" data-v="${k}" role="button" tabindex="0"><span>${l}</span><em>${v}</em></div>`; }).join('')}</div>`;
  const r=$('#kformRes'); if(!r) return;
  const bad = KFORM.filter(f=>f[3]);
  if(!KSPDONE){ r.innerHTML = `<p class="muted">اضغط على كل حقل تراه مخالفاً لقواعد طلب التكفل، ثم اضغط «تحقق». المحدد: <b class="mono">${Object.keys(KSP).filter(k=>KSP[k]).length}</b></p><button class="btn btn-primary" data-act="kcheck" style="justify-self:start">تحقق</button>`; return; }
  const hit = bad.filter(f=>KSP[f[0]]).length, fp = KFORM.filter(f=>!f[3]&&KSP[f[0]]).length;
  r.innerHTML = `<span class="score-pill">اكتشفت ${hit} من ${bad.length}${fp?` · ${fp} تحديد زائد`:''}</span><div class="review">${bad.map(f=>`<div class="rv ${KSP[f[0]]?'ok':'no'}"><b>${f[1]}</b><span>${f[4]}</span></div>`).join('')}</div><button class="btn btn-ghost" data-act="kreset" style="justify-self:start">أعد التمرين</button>`;
}

