 swap:{t:'استبدال يتامى',f:[['orph','اسم اليتيم'],['fam','رمز العائلة'],['sp','اسم الكفيل'],['code','رمز الكفيل']],
   tx:v=>`يرجى التفضل بالموافقة على استبدال اليتيم (${v.orph}) ذو رمز العائلة (${v.fam}) المكفول من قبل الكفيل (${v.sp}) رمز الكفيل (${v.code}).`},
