let KRT = 'swap', KRV = {};
function kreqRender(){
  const el=$('#kreq'); if(!el) return; const R=KREQ[KRT];
  const v = {}; R.f.forEach(([k])=>v[k] = (KRV[KRT+'.'+k]||'').trim() || '      ');
  el.innerHTML = `<div class="chips">${Object.entries(KREQ).map(([k,r])=>`<button class="chip ${k===KRT?'on':''}" data-act="kreqt" data-v="${k}">${r.t}</button>`).join('')}</div>
   <div class="kreq-grid"><div class="stack" style="gap:10px">${R.f.map(([k,l])=>`<div class="field"><label for="kr-${k}">${l}</label><input class="input" id="kr-${k}" data-in="kreq" data-k="${k}" value="${esc(KRV[KRT+'.'+k]||'')}"></div>`).join('')}</div>
   <div class="stack" style="gap:10px"><span class="eyebrow">نص طلب الخدمة — ${R.t}</span>${copyBox(R.tx(v))}${R.rule?`<div class="card pad stack" style="gap:8px"><b class="ct">الآلية المتبعة قبل الطلب</b>${steps(R.rule)}</div>`:''}</div></div>`;
}

/* age-rule calculator (k4) */
let KAGE = {g:'m', age:16, st:'y', cat:'n'};
function kageRender(){
  const el=$('#kageOut'); if(!el) return; const c=KAGE, a=+c.age;
  let t, tone='edit', s=[];
  if(c.cat!=='n'){ t='مستثنى من شرط العمر'; s=['اليتامى ذوو الاحتياجات الخاصة والمتفوقون دراسياً يُستثنون من شرط العمر لغاية إكمالهم الدراسة الجامعية.']; }
  else if(c.g==='f'){ t='الإناث مستثنيات'; s=['يُستثنى الإناث من إجراءات التبليغ عند سن 15 و18، ومن شرط أن يكون العمر عند الاحتضان أقل من 15 سنة.']; }
  else if(c.st==='y'){ if(a>=18){ t='تبليغ الكفيل'; tone='case'; s=['اليتيم مستمر بالدراسة ومكفول كفالة خاصة وبلغ 18 سنة: يُبلَّغ الكفيل عن رغبته بالاستمرار بالكفالة أو التغيير.']; } else { t='الكفالة مستمرة'; s=['يُحتضن اليتيم في المؤسسة لغاية سن 18 سنة بشرط استمراره في الدراسة.']; } }
  else { if(a>=15){ t='تبليغ الكفيل'; tone='case'; s=['اليتيم غير مستمر بالدراسة ومكفول كفالة خاصة وبلغ 15 سنة: يُبلَّغ الكفيل عن رغبته بالاستمرار أو التغيير، مع إعلامه بعدم استمرار اليتيم بالدراسة.']; } else { t='لا إجراء الآن'; s=['يكون تبليغ الكفيل بعد سن 15 سنة إذا بقي اليتيم غير مستمر بالدراسة.']; } }
  s.push('شرط الاحتضان: أن يكون سن اليتيم عند احتضانه في المؤسسة أقل من 15 سنة (يستثنى الإناث).');
  el.innerHTML = `<div class="verdict"><div class="vh"><span class="vb ${tone}">${t}</span></div>${bullets(s)}</div>`;
}

