function sfind(q){ const t=norm(q).split(/\s+/).filter(Boolean).map(w=>w.replace(/^(وال|بال|لل|ال)(?=..)/,'')); if(!t.length) return []; return SITEMS.filter(it=>t.every(w=>it.n.includes(w))); }
function sfinderRender(){
  const r=$('#sRes'); if(!r) return; const res = SQ.trim()?sfind(SQ):[];
  r.innerHTML = SQ.trim() ? (res.length ? `<div class="results">${res.slice(0,30).map(it=>`<div class="res sres"><div><div class="st">${esc(it.x)}</div><div class="ty">${esc(it.cat)}</div><p class="muted" style="font-size:.86rem;margin-top:4px">${it.rule}</p></div><span class="side side-${SIDE[it.side][1]}">${SIDE[it.side][0]}</span></div>`).join('')}</div>` : note('tip','لا توجد مادة مطابقة','المواد غير المذكورة في الدليل تُعامل كـ«مواد لم تُذكر في الجدول»: بالتنسيق مع قسم المخازن والتجهيزات أو القسم المختص، وعدم استلامها مباشرة إلا بموافقة ذوي الاختصاص.')) : '';
}
