function bcodeRender(){ const el=$('#bcodeOut'); if(!el) return; const v=BCODE.trim().toUpperCase();
  if(!v){ el.className='hint show'; el.innerHTML='اكتب باركوداً مثل <b class="mono">PB2021ANI699</b>'; return; }
  const t = BTYPES.find(b=>b[0]!=='—' && v.startsWith(b[0]));
  if(!t){ el.className='hint show bad'; el.textContent='بادئة غير معروفة. البادئات المعتمدة: PB، PS، ZB، ZS، SB، TB، LK.'; return; }
  const full = /^[A-Z]{2}\d{4}[A-Z]{3}\d{3}$/.test(v);
  el.className='hint show '+(full?'good':'bad');
  el.innerHTML = `<b>${t[1]}</b> — ${t[2]}${full?'':'<br>تحقق من بقية الرمز: نمطه في الدليل حرفان للنوع ثم أرقام وحروف مثل PB202XAAA123.'}`; }

